public static boolean shouldRender(LivingEntity entity) {
        if (ClientMagicData.getRecasts().hasRecastsActive()) {
            for (RecastInstance recastInstance : ClientMagicData.getRecasts().getActiveRecasts()) {
                if (recastInstance.getCastData() instanceof MultiTargetEntityCastData targetEntityCastData) {
                    if (targetEntityCastData.isTargeted(entity)) {
                        return true;
                    }
                }
            }
        }
        return ClientMagicData.getTargetingData().isTargeted(entity);
    }

private static Vector3f getColor(String spellId) {
        return SpellRegistry.getSpell(spellId).getTargetingColor();
    }

@Override
        public void render(PoseStack poseStack, MultiBufferSource bufferSource, int pPackedLight, T entity, float pLimbSwing, float pLimbSwingAmount, float pPartialTick, float pAgeInTicks, float pNetHeadYaw, float pHeadPitch) {
            if (shouldRender(entity)) {
                renderTargetLayer(poseStack, bufferSource, entity);
            }
        }

@Override
        public void render(PoseStack poseStack, AbstractSpellCastingMob animatable, BakedGeoModel bakedModel, RenderType renderType, MultiBufferSource bufferSource, VertexConsumer buffer, float partialTick, int packedLight, int packedOverlay) {
            if (shouldRender(animatable)) {
//                //It's upside down???
//                poseStack.mulPose(Axis.XP.rotationDegrees(180));
//                poseStack.translate(0, -(abstractSpellCastingMob.getBbWidth() + abstractSpellCastingMob.getBbHeight()) / 2, 0);
                poseStack.pushPose();
                poseStack.mulPose(Axis.XP.rotationDegrees(180));
                poseStack.translate(0, -animatable.getBoundingBox().getYsize() / 2, 0);
                renderTargetLayer(poseStack, bufferSource, animatable);
                poseStack.popPose();
            }
        }

public boolean isTargeted(Entity entity) {
        return targetUUIDs.contains(entity.getUUID());
    }

public boolean isRecastActive(RecastInstance recastInstance) {
        return recastInstance != null && recastInstance.remainingRecasts > 0 && recastInstance.remainingTicks > 0;
    }

public static ClientSpellTargetingData getTargetingData() {
        if (spellTargetingData == null)
            setTargetingData(new ClientSpellTargetingData());
        return spellTargetingData;
    }

public static void resetClientCastState(UUID playerUUID) {
        //Ironsspellbooks.logger.debug("resetClientCastState.1: instanceUUID:{}, playerUUID:{}", Minecraft.getInstance().player.getUUID(), playerUUID);

        if (Minecraft.getInstance().player.getUUID().equals(playerUUID)) {
            //Ironsspellbooks.logger.debug("resetClientCastState.1.1");
            playerMagicData.resetCastingState();
            resetTargetingData();
        }

        if (Minecraft.getInstance().player != null && Minecraft.getInstance().player.isUsingItem() && Minecraft.getInstance().player.getUUID().equals(playerUUID)) {
            //Ironsspellbooks.logger.debug("resetClientCastState.2: instanceUUID:{}, playerUUID:{}", Minecraft.getInstance().player.getUUID(), playerUUID);
            Minecraft.getInstance().player.stopUsingItem();
        }
    }

public static Vector3f deconstructRGB(int color) {
        int red = (color >> 16) & 0xFF;
        int green = (color >> 8) & 0xFF;
        int blue = color & 0xFF;

        return new Vector3f(red / 255.0f, green / 255.0f, blue / 255.0f);
    }

