@Override
    public void render(SoulTagEntity entity, float entityYaw, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        poseStack.pushPose();

        float time =
                entity.tickCount + partialTick;

        float hover =
                (float) Math.sin(time * 0.08F) * 0.05F;

        poseStack.translate(
                0.0F,
                hover,
                0.0F
        );

        float rotation = (entity.tickCount + partialTick) * 4.0F;

        poseStack.mulPose(
                Axis.YP.rotationDegrees(rotation)
        );

        Minecraft.getInstance()
                .getItemRenderer()
                .renderStatic(
                        entity.getItem(),
                        ItemDisplayContext.GROUND,
                        packedLight,
                        OverlayTexture.NO_OVERLAY,
                        poseStack,
                        buffer,
                        entity.level(),
                        entity.getId()
                );

        poseStack.popPose();

        super.render(entity, entityYaw, partialTick, poseStack, buffer, packedLight
        );
    }

@Override
    public void render(SoulPyreVisualEntity entity, float yaw, float tickDelta,
                       MatrixStack matrices, VertexConsumerProvider vertexConsumers,
                       int light) {
        if (!Config.general.enableModernFieldEffects || entity.getRadius() <= 0.05F) {
            terrainOverlay.clear(entity.getUuid());
            return;
        }

        Vec3d entityRenderPos = interpolatedPosition(entity, tickDelta);
        Entity owner = entity.getWorld().getEntityById(entity.getOwnerEntityId());
        Vec3d center = owner == null
                ? entityRenderPos
                : interpolatedPosition(owner, tickDelta);
        Vec3d offset = center.subtract(entityRenderPos);

        matrices.push();
        matrices.translate(offset.x, offset.y, offset.z);
        float radius = entity.getRadius();
        terrainOverlay.render(
                entity.getWorld(),
                entity.getUuid(),
                center.x,
                center.y,
                center.z,
                radius,
                entity.getMaxRadius(),
                entity.getVerticalRange(),
                TerrainFieldOverlayRenderer.SOUL_PYRE,
                matrices.peek(),
                vertexConsumers
        );

        float time = entity.age + tickDelta;
        float pulse = 0.5F + 0.5F * MathHelper.sin(time * 0.22F);
        VertexConsumer bands = vertexConsumers.getBuffer(RenderLayer.getDebugQuads());

        drawBand(entity, center, matrices.peek(), bands, radius, 0.085F,
                24, 180, 188, 125 + (int) (pulse * 55.0F), false, 0);
        drawBand(entity, center, matrices.peek(), bands,
                Math.max(0.1F, radius - 0.36F), 0.035F,
                65, 225, 218, 50 + (int) (pulse * 30.0F), true, 5);
        drawBand(entity, center, matrices.peek(), bands,
                Math.max(0.1F, radius * 0.58F), 0.028F,
                16, 105, 112, 35, true, 11);

        float pulseAge = time - entity.getPulseStartAge();
        if (pulseAge >= 0.0F && pulseAge <= 13.0F) {
            float progress = pulseAge / 13.0F;
            float inwardRadius = MathHelper.lerp(progress, radius, 0.25F);
            drawBand(entity, center, matrices.peek(), bands,
                    inwardRadius, 0.07F,
                    72, 245, 231,
                    (int) (145.0F * (1.0F - progress)), false, 17);
        }

        VertexConsumer glow = vertexConsumers.getBuffer(
                RenderLayer.getEntityTranslucentEmissive(WHITE_TEXTURE));
        drawPerimeterFlames(entity, center, matrices.peek(), glow, radius, time);
        drawOrbitingSouls(entity, matrices, vertexConsumers, time);
        matrices.pop();
        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

@SubscribeEvent
	public static void tickDisplay(CustomWorldRenderEvent event) {
		if (Minecraft.getMinecraft() == null) return;
		if (Minecraft.getMinecraft().player == null) return;
		if (Minecraft.getMinecraft().world == null) return;
		if (Minecraft.getMinecraft().getRenderManager() == null) return;
		if (Minecraft.getMinecraft().getRenderManager().options == null) return;

		EntityPlayer player = Minecraft.getMinecraft().player;
		World world = Minecraft.getMinecraft().world;

		if (player.isInvisible() || VanishTracker.isVanished(player)) return;

		ItemStack hand = player.getHeldItemMainhand();
		if (!(hand.getItem() instanceof ISpellCaster)) return;
		if (hand.getItem() instanceof ICooldownSpellCaster && ((ICooldownSpellCaster) hand.getItem()).isCoolingDown(world, hand))
			return;

		if (player.isSneaking()) {
			for (SpellRing spellRing : SpellUtils.getAllSpellRings(hand)) {
				if ((spellRing.getModule() != null ? spellRing.getModule().getModuleClass() : null) instanceof IBlockSelectable) {
					RayTraceResult result = Minecraft.getMinecraft().objectMouseOver;


					if (result.typeOfHit == RayTraceResult.Type.BLOCK) {
						BlockPos posHit = result.getBlockPos();
						if (player.world.isAirBlock(posHit)) return;

						RenderUtils.drawCubeOutline(event.getWorld(), posHit, event.getWorld().getBlockState(posHit));
						return;
					}
				}
			}
		}

		List<SpellRing> chains = SpellUtils.getSpellChains(hand);

		for (SpellRing chain : chains) {

			SpellData data = new SpellData();
			data.processEntity(player, true);

			SpellRing ring = chain;
			while (ring != null && ring.getModule() != null) {

				ring.getModule().renderVisualization(world, data, ring, event.getPartialTicks());

				ring = ring.getChildRing();
			}
		}
	}
